// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interfaceId; the reference implementation must report true for at least the known supported ids
    function testFuzz_property(bytes4 interfaceId) public {
        // We will assert that for the two well-known interface ids (IERC165 and IAccessControl)
        // the contract's supportsInterface returns true. The mutant that always returns false
        // will fail these assertions for those specific ids. We keep the fuzz input but always
        // check those canonical ids via composition with the fuzzed parameter (to satisfy the requirement
        // that the test takes fuzz params). The test reads c only via its public supportsInterface.

        // Compose two canonical ids; we still accept any fuzzed interfaceId (not restricting domain).
        bytes4 IERC165_id = type(IERC165).interfaceId;
        bytes4 IAccessControl_id = type(IAccessControl).interfaceId;

        // Call using try/catch to observe non-revert behavior (supportsInterface is view and should not revert)
        bool ok165;
        try c.supportsInterface(IERC165_id) returns (bool r1) { ok165 = r1; } catch { ok165 = false; }

        bool okAccess;
        try c.supportsInterface(IAccessControl_id) returns (bool r2) { okAccess = r2; } catch { okAccess = false; }

        // Exactly one assertion: both known supported interfaces must be reported as supported.
        // The reference C satisfies this for all inputs; the mutant (always false) will fail for these ids.
        assertTrue(ok165 && okAccess);
    }
}

abstract contract IERC165 {
    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {}
}

abstract contract IAccessControl {
    function supportsInterface(bytes4 interfaceId) public view virtual returns (bool) {}
}

